#!/usr/bin/env python3
"""Generates docs/datenschutz.html and docs/nutzungsbedingungen.html from the legal texts in the app
(TERMS_HTML / PRIVACY_HTML in app/assets/index.html), so the app and the website never disagree.
Run after changing those texts:  python3 build/site.py
"""
import os, re

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
SRC = os.path.join(ROOT, "app", "assets", "index.html")
OUT = os.path.join(ROOT, "docs")

PAGE = """<!doctype html>
<!-- Generated by build/site.py from app/assets/index.html - do not edit by hand. -->
<html lang="de">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="dark light">
<meta name="theme-color" content="#0f131b" media="(prefers-color-scheme: dark)">
<meta name="theme-color" content="#f4f6fb" media="(prefers-color-scheme: light)">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; img-src 'self'; style-src 'self'; base-uri 'none'; form-action 'none'">
<meta name="referrer" content="no-referrer">
<title>{title} – Group Checkan</title>
<link rel="icon" href="assets/favicon.png">
<link rel="stylesheet" href="assets/style.css">
</head>
<body class="doc">
<main class="doc-main">
  <a class="back" href="index.html">← Zurück zum Download</a>
  <article class="legal-doc">
{content}
  </article>
</main>
<footer>
  Group Checkan ist ein privates, nicht kommerzielles Hobbyprojekt von Arthurtschik, c/o Block Services,
  Stuttgarter Str. 106, 70736 Fellbach · arthurtschik.business@gmail.com
</footer>
</body>
</html>
"""


def const(src, name):
    m = re.search(r"const " + name + r"=`(.*?)`;", src, re.S)
    if not m:
        raise SystemExit(f"{name} not found in {SRC}")
    text = m.group(1)
    if "${" in text or "`" in text:
        raise SystemExit(f"{name} contains template expressions - cannot be exported as static HTML")
    return text


def main():
    src = open(SRC, encoding="utf-8").read()
    for const_name, filename, title in (("PRIVACY_HTML", "datenschutz.html", "Datenschutzhinweis"),
                                        ("TERMS_HTML", "nutzungsbedingungen.html", "Nutzungsbedingungen")):
        body = const(src, const_name)
        body = re.sub(r"^<h2>(.*?)</h2>", r"<h1>\1</h1>", body, count=1)   # page title is the main heading
        body = "\n".join("    " + line for line in body.splitlines())
        path = os.path.join(OUT, filename)
        with open(path, "w", encoding="utf-8") as f:
            f.write(PAGE.format(title=title, content=body))
        print("wrote", os.path.relpath(path, ROOT))
    open(os.path.join(OUT, ".nojekyll"), "w").close()   # serve files as they are (no Jekyll processing)


if __name__ == "__main__":
    main()
